/**
 * @ignore
 * @method
 * @name binance#parsePredictionOrder
 * @description parses a raw binance prediction order object into a unified order object
 * @param {object} order the raw order object
 * @param {object} [outcomeObj] the ourtome the order belongs to
 * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *Binance) ParsePredictionOrder(order any, optionalArgs ...any) any {
	//
	// {
	//     "orderId": "54124",
	//     "vendorOrderId": "0x1234abcd...",
	//     "vendor": "PREDICT_FUN",
	//     "marketTopicId": 4229564,
	//     "slug": "btc-price-1h-up-or-down",
	//     "marketTopicTitle": "BTC Price 1h Up or Down?",
	//     "marketId": 5567895,
	//     "marketTitle": "UP",
	//     "outcome": "YES",
	//     "outcomeIndex": 0,
	//     "status": "OPENING",
	//     "side": "BUY",
	//     "orderType": "LIMIT",
	//     "createTime": 1748131500000,
	//     "modifyTime": 1748131500000,
	//     "makerUsdtAmount": "1.00",
	//     "makerShareQty": "2000.00",
	//     "filledUsdtAmount": "0.00",
	//     "filledShareQty": "0.00",
	//     "fillPercentage": "0.00",
	//     "price": "0.50",
	//     "marketProviderFee": "0.02",
	//     "networkFee": "0.000001"
	// }
	//
	outcomeObj := ccxt.GetArg(optionalArgs, 0, nil)
	_ = outcomeObj
	var status any = this.ParseOrderStatus(this.SafeString(order, "status"))
	if ccxt.IsTrue(ccxt.IsEqual(outcomeObj, nil)) {
		var marketId any = this.SafeString(order, "marketId")
		var outcome any = this.SafeStringUpper(order, "outcome")
		var market any = this.SafeMarket(marketId)
		var outcomeName any = this.SafeString(market, "market")
		if ccxt.IsTrue(ccxt.IsEqual(outcomeName, nil)) {
			outcomeName = marketId
		}
		outcomeName = ccxt.Add(outcomeName, ccxt.Add(":", outcome))
		outcomeObj = this.SafeOutcome(outcomeName)
	}
	var side any = this.SafeStringLower(order, "side")
	var timestamp any = this.SafeInteger(order, "createTime")
	return this.SafePredictionOrder(map[string]any{
		"id":                 this.SafeString(order, "orderId"),
		"clientOrderId":      nil,
		"info":               order,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"outcome":            this.SafeString(outcomeObj, "outcome"),
		"outcomeId":          this.SafeString(outcomeObj, "id"),
		"label":              this.SafeString(outcomeObj, "label"),
		"market":             this.SafeString(outcomeObj, "market"),
		"type":               this.SafeStringLower(order, "orderType"),
		"timeInForce":        nil,
		"postOnly":           nil,
		"reduceOnly":         nil,
		"side":               side,
		"price":              this.SafeNumber(order, "price"),
		"triggerPrice":       nil,
		"amount":             nil,
		"cost":               nil,
		"average":            nil,
		"filled":             nil,
		"remaining":          nil,
		"fee":                nil,
		"trades":             []any{},
	}, outcomeObj)
}
func (this *Binance) ParseOrderStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"OPENING": "open",
		"FILLED":  "closed",
	}
	if ccxt.IsTrue(ccxt.IsEqual(status, nil)) {
		return nil
	}
	if ccxt.IsTrue(ccxt.EndsWith(status, "Rejected")) {
		return "rejected"
	}
	if ccxt.IsTrue(ccxt.EndsWith(status, "Canceled")) {
		return "canceled"
	}
	return this.SafeString(statuses, status, status)
}

