/**
 * @ignore
 * @method
 * @name binance#parsePredictionTrade
 * @description parses a single binance fill into a unified trade object
 * @param {object} trade the raw fill object
 * @param {object} [outcomeObj] the outcome the trade belongs to
 * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
 */
func (this *Binance) ParsePredictionTrade(trade any, optionalArgs ...any) any {
	//
	// {
	//     "orderId": "54124",
	//     "vendorOrderId": "0x1234abcd...",
	//     "vendor": "PREDICT_FUN",
	//     "marketTopicId": 4229564,
	//     "slug": "btc-price-1h-up-or-down",
	//     "marketTopicTitle": "BTC Price 1h Up or Down?",
	//     "marketId": 5567895,
	//     "marketTitle": "UP",
	//     "outcome": "YES",
	//     "outcomeIndex": 0,
	//     "status": "OPENING",
	//     "side": "BUY",
	//     "orderType": "LIMIT",
	//     "createTime": 1748131500000,
	//     "modifyTime": 1748131500000,
	//     "makerUsdtAmount": "1.00",
	//     "makerShareQty": "2000.00",
	//     "filledUsdtAmount": "0.00",
	//     "filledShareQty": "0.00",
	//     "fillPercentage": "0.00",
	//     "price": "0.50",
	//     "marketProviderFee": "0.02",
	//     "networkFee": "0.000001"
	// }
	//
	outcomeObj := ccxt.GetArg(optionalArgs, 0, nil)
	_ = outcomeObj
	if ccxt.IsTrue(ccxt.IsEqual(outcomeObj, nil)) {
		var marketId any = this.SafeString(trade, "marketId")
		var outcome any = this.SafeStringUpper(trade, "outcome")
		var market any = this.SafeMarket(marketId)
		var outcomeName any = this.SafeString(market, "market")
		if ccxt.IsTrue(ccxt.IsEqual(outcomeName, nil)) {
			outcomeName = marketId
		}
		outcomeName = ccxt.Add(outcomeName, ccxt.Add(":", outcome))
		outcomeObj = this.SafeOutcome(outcomeName)
	}
	var timestamp any = this.SafeInteger(trade, "createTime")
	var filled any = this.SafeString(trade, "filledShareQty")
	var cost any = this.SafeString(trade, "filledUsdtAmount")
	var price any = this.SafeString(trade, "price")
	var orderType any = this.SafeStringLower(trade, "orderType")
	var fee any = nil
	if ccxt.IsTrue(ccxt.IsTrue(ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(orderType, "market"))) && ccxt.IsTrue((!ccxt.IsEqual(cost, nil)))) && ccxt.IsTrue((!ccxt.IsEqual(price, nil)))) && ccxt.IsTrue((!ccxt.IsEqual(filled, nil)))) {
		// buys pay cost above price*filled, sells receive proceeds net of the fee —
		// either way the fee is the absolute difference
		var feeCost any = ccxt.Precise.StringAbs(ccxt.Precise.StringSub(cost, ccxt.Precise.StringMul(price, filled)))
		fee = map[string]any{
			"currency": "USDT",
			"cost":     this.ParseNumber(feeCost),
		}
	}
	return this.SafePredictionTrade(map[string]any{
		"id":                 nil,
		"info":               trade,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": this.SafeInteger(trade, "modifyTime"),
		"outcome":            this.SafeString(outcomeObj, "outcome"),
		"outcomeId":          this.SafeString(outcomeObj, "id"),
		"label":              this.SafeString(outcomeObj, "label"),
		"market":             this.SafeString(outcomeObj, "market"),
		"order":              this.SafeString(trade, "orderId"),
		"type":               orderType,
		"side":               this.SafeStringLower(trade, "side"),
		"takerOrMaker":       nil,
		"price":              price,
		"amount":             this.SafeString(trade, "makerShareQty"),
		"filled":             filled,
		"cost":               cost,
		"fee":                fee,
	}, outcomeObj)
}

